CREATE TABLE public.contact_grants (
    id bigint NOT NULL,
    request_id bigint NOT NULL,
    leader_id bigint NOT NULL,
    subject_user_id bigint NOT NULL,
    context_type text NOT NULL,
    context_id bigint NOT NULL,
    fields text NOT NULL,
    granted_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    end_reason text DEFAULT ''::text NOT NULL,
    ended_by bigint,
    CONSTRAINT contact_grants_check CHECK ((((ended_at IS NULL) AND (end_reason = ''::text) AND (ended_by IS NULL)) OR ((ended_at IS NOT NULL) AND (ended_at >= granted_at) AND (((end_reason = ANY (ARRAY['revoked_by_subject'::text, 'revoked_by_admin'::text, 'revoked_by_guardian'::text])) AND (ended_by IS NOT NULL) AND (ended_by > 0)) OR ((end_reason = ANY (ARRAY['left_role'::text, 'left_context'::text, 'context_ended'::text, 'turned_18'::text, 'account_disabled'::text, 'event_ended'::text])) AND (ended_by IS NULL)))))),
    CONSTRAINT contact_grants_check1 CHECK (((end_reason <> 'revoked_by_subject'::text) OR (ended_by = subject_user_id)))
);


