--
-- Name: contact_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contact_requests (
    id bigint NOT NULL,
    requester_id bigint NOT NULL,
    subject_user_id bigint NOT NULL,
    context_type text NOT NULL,
    context_id bigint NOT NULL,
    fields text NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    needs_admin boolean NOT NULL,
    subject_decision text DEFAULT 'pending'::text NOT NULL,
    subject_decided_by bigint,
    subject_decided_at timestamp with time zone,
    admin_decision text NOT NULL,
    admin_decided_by bigint,
    admin_decided_at timestamp with time zone,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    withdrawn_by_id bigint,
    end_reason text DEFAULT ''::text NOT NULL,
    purpose text DEFAULT 'contact'::text NOT NULL,
    occurrence_id bigint,
    add_over_limit boolean DEFAULT false NOT NULL,
    add_over_capacity boolean DEFAULT false NOT NULL,
    add_attendance_mode text DEFAULT ''::text NOT NULL,
    add_guest_count bigint DEFAULT 0 NOT NULL,
    add_childcare_count bigint DEFAULT 0 NOT NULL,
    add_childcare_ages_note text DEFAULT ''::text NOT NULL,
    completed_target_id bigint,
    CONSTRAINT contact_requests_add_completion CHECK (((purpose = 'contact'::text) OR ((status = 'granted'::text) AND (completed_target_id IS NOT NULL) AND (completed_target_id > 0)) OR ((status <> 'granted'::text) AND (completed_target_id IS NULL)))),
    CONSTRAINT contact_requests_admin_decision_check CHECK ((admin_decision = ANY (ARRAY['pending'::text, 'approved'::text, 'denied'::text, 'not_needed'::text]))),
    CONSTRAINT contact_requests_check CHECK (((subject_user_id > 0) AND (subject_user_id <> requester_id))),
    CONSTRAINT contact_requests_check1 CHECK ((expires_at > created_at)),
    CONSTRAINT contact_requests_check12 CHECK (((status <> ALL (ARRAY['granted'::text, 'denied'::text, 'withdrawn'::text])) OR (completed_at < expires_at))),
    CONSTRAINT contact_requests_check13 CHECK (((status <> 'expired'::text) OR (completed_at >= expires_at))),
    CONSTRAINT contact_requests_check2 CHECK ((((subject_decision = 'pending'::text) AND (subject_decided_by IS NULL) AND (subject_decided_at IS NULL)) OR ((subject_decision <> 'pending'::text) AND (subject_decided_by IS NOT NULL) AND (subject_decided_by = subject_user_id) AND (subject_decided_at IS NOT NULL)))),
    CONSTRAINT contact_requests_check3 CHECK (((needs_admin AND (admin_decision <> 'not_needed'::text)) OR ((NOT needs_admin) AND (admin_decision = 'not_needed'::text)))),
    CONSTRAINT contact_requests_check4 CHECK ((((admin_decision = ANY (ARRAY['pending'::text, 'not_needed'::text])) AND (admin_decided_by IS NULL) AND (admin_decided_at IS NULL)) OR ((admin_decision = ANY (ARRAY['approved'::text, 'denied'::text])) AND (admin_decided_by IS NOT NULL) AND (admin_decided_by > 0) AND (admin_decided_at IS NOT NULL)))),
    CONSTRAINT contact_requests_check5 CHECK (((subject_decided_at IS NULL) OR ((subject_decided_at >= created_at) AND (subject_decided_at < expires_at)))),
    CONSTRAINT contact_requests_check6 CHECK (((admin_decided_at IS NULL) OR ((admin_decided_at >= created_at) AND (admin_decided_at < expires_at)))),
    CONSTRAINT contact_requests_check7 CHECK ((((status = 'pending'::text) AND (completed_at IS NULL)) OR ((status <> 'pending'::text) AND (completed_at IS NOT NULL) AND (completed_at >= created_at)))),
    CONSTRAINT contact_requests_check8 CHECK (((completed_at IS NULL) OR (((subject_decided_at IS NULL) OR (subject_decided_at <= completed_at)) AND ((admin_decided_at IS NULL) OR (admin_decided_at <= completed_at))))),
    CONSTRAINT contact_requests_check9 CHECK ((((status = 'withdrawn'::text) AND (withdrawn_by_id IS NOT NULL) AND (withdrawn_by_id = requester_id)) OR ((status <> 'withdrawn'::text) AND (withdrawn_by_id IS NULL)))),
    CONSTRAINT contact_requests_context_id_check CHECK ((context_id > 0)),
    CONSTRAINT contact_requests_context_type_check CHECK ((context_type = ANY (ARRAY['group'::text, 'event'::text]))),
    CONSTRAINT contact_requests_end_reason CHECK ((((status = 'ended'::text) AND ((end_reason = ANY (ARRAY['left_role'::text, 'left_context'::text, 'context_ended'::text, 'turned_18'::text, 'account_disabled'::text, 'event_ended'::text])) OR ((purpose <> 'contact'::text) AND (end_reason = ANY (ARRAY['blocked'::text, 'removed'::text, 'occurrence_cancelled'::text, 'occurrence_deleted'::text, 'event_deleted'::text, 'group_deleted'::text, 'consent_lost'::text, 'context_changed'::text, 'already_added'::text]))))) OR ((status <> 'ended'::text) AND (end_reason = ''::text)))),
    CONSTRAINT contact_requests_outcome CHECK ((((status = 'granted'::text) AND (subject_decision = 'approved'::text) AND (admin_decision = ANY (ARRAY['approved'::text, 'not_needed'::text]))) OR ((status = 'denied'::text) AND ((subject_decision = 'denied'::text) OR (admin_decision = 'denied'::text))) OR ((status = ANY (ARRAY['pending'::text, 'withdrawn'::text, 'expired'::text, 'ended'::text])) AND (subject_decision <> 'denied'::text) AND (admin_decision <> 'denied'::text) AND ((purpose <> 'contact'::text) OR (NOT ((subject_decision = 'approved'::text) AND (admin_decision = ANY (ARRAY['approved'::text, 'not_needed'::text])))))))),
    CONSTRAINT contact_requests_purpose_scope CHECK ((((purpose = 'contact'::text) AND (fields = ANY (ARRAY['email'::text, 'phone'::text, 'both'::text])) AND (occurrence_id IS NULL) AND (NOT add_over_limit) AND (NOT add_over_capacity) AND (add_attendance_mode = ''::text) AND (add_guest_count = 0) AND (add_childcare_count = 0) AND (add_childcare_ages_note = ''::text) AND (completed_target_id IS NULL)) OR ((purpose = 'group_add'::text) AND (context_type = 'group'::text) AND (fields = ''::text) AND (occurrence_id IS NULL) AND (NOT add_over_capacity) AND (add_attendance_mode = ''::text) AND (add_guest_count = 0) AND (add_childcare_count = 0) AND (add_childcare_ages_note = ''::text)) OR ((purpose = 'occurrence_add'::text) AND (context_type = 'event'::text) AND (fields = ''::text) AND (occurrence_id IS NOT NULL) AND (occurrence_id > 0) AND (NOT add_over_limit) AND (add_attendance_mode = ANY (ARRAY['in_person'::text, 'remote'::text])) AND ((add_guest_count >= 0) AND (add_guest_count <= 5)) AND ((add_childcare_count >= 0) AND (add_childcare_count <= 20)) AND (char_length(add_childcare_ages_note) <= 200)))),
    CONSTRAINT contact_requests_reason_check CHECK ((char_length(reason) <= 1000)),
    CONSTRAINT contact_requests_requester_id_check CHECK ((requester_id > 0)),
    CONSTRAINT contact_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'granted'::text, 'denied'::text, 'withdrawn'::text, 'expired'::text, 'ended'::text]))),
    CONSTRAINT contact_requests_subject_decision_check CHECK ((subject_decision = ANY (ARRAY['pending'::text, 'approved'::text, 'denied'::text])))
);


