    CONSTRAINT registrations_childcare_count_check CHECK ((childcare_count >= 0)),
    CONSTRAINT registrations_guest_count_check CHECK ((guest_count >= 0)),
    CONSTRAINT registrations_holder CHECK ((((household_person_id IS NOT NULL) AND (registered_by IS NOT NULL)) OR ((user_id IS NOT NULL) AND (registered_by IS NULL)))),
    CONSTRAINT registrations_named_care CHECK (((NOT childcare_requested) OR ((household_person_id IS NOT NULL) AND (attendance_mode = 'in_person'::text)))),
    CONSTRAINT registrations_named_party CHECK (((household_person_id IS NULL) OR ((guest_count = 0) AND (childcare_count = 0) AND (childcare_ages_note = ''::text)))),
    CONSTRAINT registrations_source_check CHECK ((source = ANY (ARRAY['web'::text, 'admin'::text, 'guest_form'::text]))),
    CONSTRAINT registrations_status_check CHECK ((status = ANY (ARRAY['going'::text, 'maybe'::text, 'declined'::text, 'cancelled'::text, 'waitlisted'::text, 'removed'::text]))),
    CONSTRAINT registrations_subject CHECK (((user_id IS NOT NULL) <> (household_person_id IS NOT NULL)))
);


