    CONSTRAINT room_bookings_setup_minutes_check CHECK (((setup_minutes >= 0) AND (setup_minutes <= 240))),
    CONSTRAINT room_bookings_status_check CHECK ((status = ANY (ARRAY['confirmed'::text, 'requested'::text, 'rejected'::text]))),
    CONSTRAINT room_bookings_teardown_minutes_check CHECK (((teardown_minutes >= 0) AND (teardown_minutes <= 240))),
    CONSTRAINT room_bookings_times CHECK ((ends_at > starts_at))
);


